root/
├── users/                          ← collection
│   ├── u_abc123/                   ← document (max 1 MiB)
│   │   ├── name: 'Ada Lovelace'
│   │   ├── email: 'ada@x.com'
│   │   ├── createdAt: <timestamp>
│   │   └── orders/                 ← subcollection
│   │       ├── o_001/  { total: 100, ... }
│   │       └── o_002/  { total: 250, ... }
│   └── u_def456/  { ... }
│
├── products/
│   ├── p_pixel8/  { name, price, stock, tags: [...] }
│   └── p_iphone15/  { ... }
│
└── chats/
    └── c_xyz/
        ├── participants: ['u_abc123', 'u_def456']
        └── messages/               ← subcollection
            ├── m_001/  { text, from, ts }
            └── m_002/  { ... }

import 'package:cloud_firestore/cloud_firestore.dart';

final db = FirebaseFirestore.instance;

// ────── CREATE ──────
await db.collection('users').doc(uid).set({
  'name': 'Ada Lovelace',
  'email': 'ada@x.com',
  'createdAt': FieldValue.serverTimestamp(),  // server-side clock, not client
  'orderCount': 0,
});

// Auto-generated ID:
final ref = await db.collection('orders').add({'total': 100, 'userId': uid});
print('New order: ${ref.id}');

// ────── READ (one-shot) ──────
final snap = await db.collection('users').doc(uid).get();
if (snap.exists) {
  final data = snap.data()!;
  print(data['name']);
}

// ────── UPDATE (partial) ──────
await db.collection('users').doc(uid).update({
  'orderCount': FieldValue.increment(1),  // atomic
  'lastLogin': FieldValue.serverTimestamp(),
});

// Array ops (atomic, no read-modify-write):
await db.collection('users').doc(uid).update({
  'tags': FieldValue.arrayUnion(['flutter']),   // add if not present
  'blocked': FieldValue.arrayRemove(['spammer']),
});

// ────── DELETE ──────
await db.collection('users').doc(uid).delete();
// NOTE: doesn't delete subcollections! Use a Cloud Function or admin tool.

// ────── QUERY ──────
// Simple filter + order + limit:
final recentOrders = await db.collection('orders')
    .where('userId', isEqualTo: uid)
    .where('status', isEqualTo: 'paid')
    .orderBy('createdAt', descending: true)
    .limit(20)
    .get();

for (final doc in recentOrders.docs) {
  print('${doc.id} → ${doc.data()}');
}

// Multiple where + orderBy → Firestore will PROMPT for a composite index.
// Click the link in the error → auto-creates the index in the console.

// ────── REAL-TIME LISTENER ──────
final sub = db.collection('chats').doc(chatId).collection('messages')
    .orderBy('ts', descending: true).limit(50)
    .snapshots()  // Stream<QuerySnapshot>
    .listen((snap) {
      for (final change in snap.docChanges) {
        if (change.type == DocumentChangeType.added) {
          print('new: ${change.doc.data()}');
        }
      }
    });

// Dispose when leaving the screen:
await sub.cancel();

// ────── PAGINATION (cursor-based) ──────
QuerySnapshot? lastPage;
final firstPage = await db.collection('orders')
    .orderBy('createdAt', descending: true).limit(20).get();

// Next page:
final nextPage = await db.collection('orders')
    .orderBy('createdAt', descending: true)
    .startAfterDocument(firstPage.docs.last)   // cursor
    .limit(20).get();

// ────── BATCH WRITE (max 500 ops) ──────
final batch = db.batch();
batch.set(db.collection('orders').doc('o1'), {'total': 100});
batch.update(db.collection('users').doc(uid), {'orderCount': FieldValue.increment(1)});
batch.delete(db.collection('carts').doc(uid));
await batch.commit();  // atomic — all or none

// ────── TRANSACTION (max 500 ops, retry on conflict) ──────
await db.runTransaction((tx) async {
  final snap = await tx.get(db.collection('inventory').doc('p_pixel8'));
  final stock = snap['stock'] as int;
  if (stock < 1) throw Exception('Out of stock');
  tx.update(snap.reference, {'stock': stock - 1});
});

// firestore.rules — deployed via `firebase deploy --only firestore:rules`
rules_version = '2';
service cloud.firestore {
  match /databases/{db}/documents {

    // Users can only read/write their own document.
    match /users/{uid} {
      allow read: if request.auth.uid == uid;
      allow write: if request.auth.uid == uid
        && request.resource.data.email == resource.data.email;  // can't change email
    }

    // Orders — owner-based:
    match /orders/{orderId} {
      allow read: if request.auth.uid == resource.data.userId;
      allow create: if request.auth.uid == request.resource.data.userId
        && request.resource.data.total is number
        && request.resource.data.total > 0;
      allow update: if request.auth.uid == resource.data.userId
        && request.resource.data.userId == resource.data.userId;  // can't reassign
      allow delete: if false;  // never delete — soft-delete only
    }

    // Admin-only via custom claim:
    match /reports/{doc} {
      allow read, write: if request.auth.token.role == 'admin';
    }

    // Public read, auth write:
    match /products/{prod} {
      allow read: if true;
      allow write: if request.auth.token.role in ['admin', 'editor'];
    }

    // Multi-tenant:
    match /tenants/{tenantId}/{doc=**} {
      allow read, write: if request.auth.token.tenantId == tenantId;
    }

    // Default deny — anything not matched:
    match /{document=**} {
      allow read, write: if false;
    }
  }
}

